        mbar_wait(PF[0],ppf[0]); ppf[0]^=1; if constexpr(CORR){ mbar_wait(CO[0],pco[0]); pco[0]^=1; } pv(0,i);
        mbar_wait(PF[1],ppf[1]); ppf[1]^=1; if constexpr(CORR){ mbar_wait(CO[1],pco[1]); pco[1]^=1; } pv(1,i);
        mma_commit(KVE[s]);
        if(i+1<NBk){ int ns=(i+1)%WST; mbar_wait(KVF[ns],pf[ns]); pf[ns]^=1; qk(0,i+1); qk(1,i+1); }
    }
}

