            if(i+1<NBk){ int ns=(i+1)%WST,nj=(i+1)&1; mbar_wait(KVF[ns],pf[ns]); pf[ns]^=1; mbar_wait(SE[nj],pse[nj]); pse[nj]^=1; qk(i+1); }
