// Named (hardware) barriers for the softmax->MMA P-ready handshake. FA4 uses these (bar.arrive/bar.sync,
// e.g. sm_stats_barrier) instead of mbarriers for intra-CTA producer/consumer: a single HW barrier op that
// blocks WITHOUT the mbarrier try_wait BUSY-SPIN (the @!P5 BRA SYNCS.PHASECHK loop that was the MMA's #1
// stall + a chunk of our 1.38x instruction excess) and WITHOUT the smem barrier-state poll. Producer does
// bar.arrive (non-blocking); consumer does bar.sync (blocks until `cnt` threads total have arrived). No
// phase bit -> we alternate 2 barrier IDs per tile (parity = block&1) so a producer <=1 block ahead never
// collides. NB: only usable where BOTH sides are regular thread arrives (PF); SF/OR/KVF are signaled by
// tcgen05.commit / TMA which can ONLY complete mbarriers.
__device__ __forceinline__ void nbar_arrive(int id,int cnt){ asm volatile("bar.arrive %0, %1;"::"r"(id),"r"(cnt):"memory"); }
__device__ __forceinline__ void nbar_sync(int id,int cnt){ asm volatile("bar.sync %0, %1;"::"r"(id),"r"(cnt):"memory"); }

