import {
  Stack,
  Grid,
  Row,
  Spacer,
  H1,
  H2,
  H3,
  Text,
  Code,
  Stat,
  Table,
  Callout,
  BarChart,
  Divider,
  type TableRowTone,
  type ChartTone,
} from "cursor/canvas";

type Row = { name: string; ratio: number; fa4: number; ours: number };

// ---- Decode / KV-cache scenarios (fa3_kv_*) ----
const decode: Row[] = [
  { name: "page128", ratio: 1.109, fa4: 65.0, ours: 58.6 },
  { name: "dec1024", ratio: 1.072, fa4: 63.3, ours: 59.0 },
  { name: "page4", ratio: 1.068, fa4: 63.3, ours: 59.2 },
  { name: "page1", ratio: 1.063, fa4: 63.0, ours: 59.2 },
  { name: "decode_mqa32", ratio: 1.056, fa4: 61.5, ours: 58.2 },
  { name: "local_decode", ratio: 1.034, fa4: 62.9, ours: 60.9 },
  { name: "decode_noncausal", ratio: 1.012, fa4: 62.2, ours: 61.4 },
  { name: "decode_gqa5", ratio: 1.003, fa4: 64.0, ours: 63.8 },
  { name: "split2", ratio: 0.971, fa4: 77.9, ours: 80.3 },
  { name: "fp16_decode", ratio: 0.875, fa4: 62.5, ours: 71.4 },
  { name: "dec800", ratio: 0.863, fa4: 63.3, ours: 73.3 },
  { name: "decode_mha", ratio: 0.83, fa4: 67.0, ours: 80.8 },
  { name: "dec339", ratio: 0.828, fa4: 44.1, ours: 53.3 },
  { name: "decode_qlen8", ratio: 0.793, fa4: 67.7, ours: 85.4 },
  { name: "ctx20k", ratio: 0.669, fa4: 76.3, ours: 114.1 },
  { name: "decode_qlen120", ratio: 0.611, fa4: 81.1, ours: 132.8 },
  { name: "prefill3577", ratio: 0.315, fa4: 126.7, ours: 402.1 },
];
// hd64_decode_gqa3 belongs here too but is hd64 — keep with the rest
decode.splice(1, 0, { name: "hd64_decode_gqa3", ratio: 1.094, fa4: 61.8, ours: 56.5 });

// ---- Dense prefill / full-attention (fa3_dense_*, + the one varlen that runs) ----
const prefill: Row[] = [
  { name: "seq256", ratio: 0.731, fa4: 48.9, ours: 67.0 },
  { name: "noncausal", ratio: 0.726, fa4: 113.4, ours: 156.2 },
  { name: "kgtq", ratio: 0.724, fa4: 52.9, ours: 73.0 },
  { name: "hd64_fp16", ratio: 0.666, fa4: 91.3, ours: 137.2 },
  { name: "hd64_causal", ratio: 0.659, fa4: 90.0, ours: 136.6 },
  { name: "seq16k", ratio: 0.655, fa4: 857.1, ours: 1308.7 },
  { name: "fp16", ratio: 0.639, fa4: 100.1, ours: 156.6 },
  { name: "hd128_causal", ratio: 0.632, fa4: 98.8, ours: 156.4 },
  { name: "seq8k", ratio: 0.624, fa4: 460.9, ours: 739.0 },
  { name: "gqa", ratio: 0.615, fa4: 94.0, ours: 152.8 },
  { name: "mqa", ratio: 0.615, fa4: 93.3, ours: 151.6 },
  { name: "sink", ratio: 0.612, fa4: 99.5, ours: 162.7 },
  { name: "hd96_causal", ratio: 0.593, fa4: 94.5, ours: 159.5 },
  { name: "local", ratio: 0.573, fa4: 82.9, ours: 144.6 },
  { name: "large4k", ratio: 0.565, fa4: 156.0, ours: 276.0 },
  { name: "local_noncausal", ratio: 0.559, fa4: 93.8, ours: 168.0 },
  { name: "varlen_hd192_dv128", ratio: 0.507, fa4: 46.7, ours: 92.1 },
  { name: "hd192_dv128", ratio: 0.212, fa4: 106.1, ours: 500.7 },
];

// ---- Configs where we beat FA4 because its oracle path is slow ----
const oracleSlow: Row[] = [
  { name: "softcap", ratio: 2.032, fa4: 403.2, ours: 198.4 },
  { name: "splits3", ratio: 1.844, fa4: 282.0, ours: 153.0 },
  { name: "softcap_gqa", ratio: 1.723, fa4: 339.2, ours: 196.9 },
];

const hangs = [
  "dense_hd128_oddseq",
  "dense_hd128_deg_q239k1",
  "varlen_hd128_causal",
  "varlen_hd128_noncausal",
  "varlen_hd64_causal",
  "varlen_hd128_mqa",
  "varlen_hd128_local",
  "varlen_hd128_sink",
];

const unsupported = [
  "dense_hd192_causal",
  "dense_hd256_causal",
  "dense_hd192_fp16",
  "dense_hd128_fp8",
  "dense_hd128_fp8_gqa",
  "varlen_hd128_fp8",
  "kv_hd256_decode_mqa16",
  "kv_hd256_split_auto",
  "kv_hd128_fp8_decode",
  "kv_hd64_fp8_decode",
];

function toneFor(r: number): TableRowTone {
  if (r >= 1.0) return "success";
  if (r >= 0.85) return "info";
  if (r >= 0.7) return "warning";
  return "danger";
}

function median(xs: number[]): number {
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}

function ratioTable(rows: Row[]) {
  return (
    <Table
      headers={["Scenario", "vs FA4", "FA4 (µs)", "Ours (µs)"]}
      columnAlign={["left", "right", "right", "right"]}
      rowTone={rows.map((r) => toneFor(r.ratio))}
      striped
      rows={rows.map((r) => [
        r.name,
        `${r.ratio.toFixed(3)}x`,
        r.fa4.toFixed(1),
        r.ours.toFixed(1),
      ])}
    />
  );
}

function ratioChart(rows: Row[], height: number) {
  return (
    <BarChart
      horizontal
      height={height}
      categories={rows.map((r) => r.name)}
      series={[{ name: "Speed vs FA4", data: rows.map((r) => r.ratio), tone: "info" as ChartTone }]}
      valueSuffix="x"
      showValues
      referenceLines={[{ value: 1.0, label: "parity", tone: "success" }]}
    />
  );
}

export default function FA4PerformanceOverview() {
  const all = [...decode, ...prefill];
  const atParity = all.filter((r) => r.ratio >= 1.0).length;
  const decodeMed = median(decode.map((r) => r.ratio));
  const prefillMed = median(prefill.map((r) => r.ratio));

  return (
    <Stack gap={20} style={{ padding: 24, maxWidth: 1080 }}>
      <Stack gap={4}>
        <H1>FA4 candidate — performance across scenarios</H1>
        <Text tone="secondary">
          <Code>kernels/fa4_blackwell.cu</Code> vs vLLM FA4 oracle · lower µs is better, ratio ={" "}
          FA4 / ours (≥1.0 = at/above FA4) · Blackwell SM100 · 58 scenarios · captured Jul 5 2026
        </Text>
      </Stack>

      <Grid columns={5} gap={12}>
        <Stat value={`${atParity}`} label="at/above parity (of 36 timed)" tone="success" />
        <Stat value={`${decodeMed.toFixed(2)}x`} label="median — decode / KV" tone="success" />
        <Stat value={`${prefillMed.toFixed(2)}x`} label="median — dense prefill" tone="warning" />
        <Stat value={`${hangs.length}`} label="hang / deadlock" tone="danger" />
        <Stat value={`${unsupported.length}`} label="unsupported (build)" />
      </Grid>

      <Callout tone="danger" title="Correctness / robustness gaps outrank the perf gap right now">
        <Text>
          8 scenarios <Text weight="semibold">deadlock the kernel</Text> (spin at 100% GPU / 0%
          mem, killed at a 150s timeout): <Text weight="semibold">every standard varlen shape</Text>,
          plus the two degenerate dense shapes <Code>oddseq</Code> and <Code>deg_q239k1</Code>. A
          further 10 shapes are rejected at build time (all fp8, and head-dim ≥ 192). Only{" "}
          <Code>varlen_hd192_dv128</Code> survives among varlen configs.
        </Text>
      </Callout>

      <Stack gap={8}>
        <H2>Decode / KV-cache</H2>
        <Text tone="secondary">
          Strongest area — median <Text weight="semibold">{decodeMed.toFixed(2)}x</Text>. Paged,
          local, GQA/MQA and mid-length decode land at or above FA4. Weak spots are short-query
          batches (<Code>qlen120</Code>, <Code>qlen8</Code>) and the long-context /
          prefill-shaped cases (<Code>ctx20k</Code>, <Code>prefill3577</Code>).
        </Text>
        {ratioChart(decode, 430)}
        {ratioTable(decode)}
        <Text tone="tertiary" size="small">
          <Code>kv_hd128_leftpad</Code>: correct but no FA4 oracle available, so no ratio.
        </Text>
      </Stack>

      <Divider />

      <Stack gap={8}>
        <H2>Dense prefill / full-attention</H2>
        <Text tone="secondary">
          The persistent gap — clustered around <Text weight="semibold">0.6x</Text> (~60% of FA4).
          This is the hand-CUDA single-CTA structural local optimum discussed in the distillation
          notes. <Code>hd192_dv128</Code> (0.21x) is a pathological outlier.
        </Text>
        {ratioChart(prefill, 430)}
        {ratioTable(prefill)}
      </Stack>

      <Divider />

      <Stack gap={8}>
        <H3>Where we "beat" FA4 (FA4 oracle takes a slow path)</H3>
        <Text tone="secondary">
          Not a real win — softcap and many-split configs hit a slow FA4 reference path, so the
          ratio flatters us rather than reflecting a faster kernel.
        </Text>
        {ratioTable(oracleSlow)}
      </Stack>

      <Divider />

      <Grid columns={2} gap={20}>
        <Stack gap={8}>
          <H3>Hangs / deadlocks (8)</H3>
          <Table
            headers={["Scenario", "Status"]}
            rowTone={hangs.map(() => "danger" as TableRowTone)}
            rows={hangs.map((n) => [n, "deadlock (timeout)"])}
          />
        </Stack>
        <Stack gap={8}>
          <H3>Unsupported at build (10)</H3>
          <Table
            headers={["Scenario", "Reason"]}
            rowTone={unsupported.map(() => "neutral" as TableRowTone)}
            rows={unsupported.map((n) => [
              n,
              n.includes("fp8") ? "fp8 path not built" : "head-dim ≥ 192",
            ])}
          />
        </Stack>
      </Grid>
    </Stack>
  );
}

